                  </div>
                </div>
              </div>

              {/* SECTION 4: AGENDA */}
              <div className="horizontal-section bg-black flex items-center px-10 md:px-20">
                <div className="w-full max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-20 items-center">
                  <div>
                    <h2 className="text-primary text-[10px] font-black tracking-[0.5em] uppercase mb-4">Let's talk</h2>
