              <div className="horizontal-section flex items-center justify-center px-10 md:px-20">
                <Footer onNavigate={setCurrentPage} />
              </div>

              {/* SECTION 6: NEXUS */}
              <NeuralNexusSection />
            </div>

            {/* PROGRESS BAR */}
            <div className="fixed bottom-0 left-20 w-[calc(100%-5rem)] h-1 bg-white/5 z-[100]">
