        {currentPage === 'services' && (
          <div className="min-h-screen py-32 px-10 max-w-6xl mx-auto">
            <h1 className="text-5xl md:text-7xl font-bold text-primary mb-12">{SERVICES_PAGE_CONTENT.title}</h1>
