        )}
      </main>

      <VideoModal 
        url={modalVideo.url} 
        isOpen={modalVideo.isOpen} 
        onClose={closeVideoModal} 
      />

      <RegistrationModal 
        isOpen={isDiscountOpen} 
        onClose={() => setIsDiscountOpen(false)} 
      />

      <WhatsAppButton />
      <ChatBot />
    </div>
  );
};

export default App;

