import React, { useEffect, useRef } from 'react';

const NeuralNexusSection: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width: number, height: number, points: any[], target: any, animateHeader = true;

    // Main logic for the constellation effect
    const initHeader = () => {
      width = containerRef.current?.clientWidth || window.innerWidth;
      height = containerRef.current?.clientHeight || window.innerHeight;
      target = { x: width / 2, y: height / 2 };

      canvas.width = width;
      canvas.height = height;

      // create points
      points = [];
      const spacing = width > 768 ? 40 : 20; // Density control
      for (let x = 0; x < width; x = x + width / spacing) {
        for (let y = 0; y < height; y = y + height / spacing) {
          const px = x + Math.random() * width / spacing;
          const py = y + Math.random() * height / spacing;
          const p = { x: px, originX: px, y: py, originY: py };
          points.push(p);
        }
      }

      // for each point find the 5 closest points
      for (let i = 0; i < points.length; i++) {
        const closest = [];
        const p1 = points[i];
        for (let j = 0; j < points.length; j++) {
          const p2 = points[j];
          if (p1 !== p2) {
            let placed = false;
            for (let k = 0; k < 5; k++) {
              if (!placed) {
                if (closest[k] === undefined) {
                  closest[k] = p2;
                  placed = true;
                }
              }
            }

            for (let k = 0; k < 5; k++) {
              if (!placed) {
                if (getDistance(p1, p2) < getDistance(p1, closest[k])) {
                  closest[k] = p2;
                  placed = true;
                }
              }
            }
          }
        }
        p1.closest = closest;
      }

      // assign a circle to each point
      for (const i in points) {
        const c = new Circle(points[i], 2 + Math.random() * 2, 'rgba(255,255,255,0.3)');
        points[i].circle = c;
      }
    };

    // Event handling
    const addListeners = () => {
      window.addEventListener('resize', resize);
    };

    const resize = () => {
      if (!containerRef.current) return;
      width = containerRef.current.clientWidth;
      height = containerRef.current.clientHeight;
      canvas.width = width;
      canvas.height = height;
    };

    // Animation
    const animate = () => {
      if (animateHeader) {
        ctx.clearRect(0, 0, width, height);
        for (const i in points) {
          // detect points in range
          if (Math.abs(getDistance(target, points[i])) < 4000) {
            points[i].active = 0.3;
            points[i].circle.active = 0.6;
          } else if (Math.abs(getDistance(target, points[i])) < 20000) {
            points[i].active = 0.1;
            points[i].circle.active = 0.3;
          } else if (Math.abs(getDistance(target, points[i])) < 40000) {
            points[i].active = 0.02;
            points[i].circle.active = 0.1;
          } else {
            points[i].active = 0;
            points[i].circle.active = 0;
          }

          drawLines(points[i]);
          points[i].circle.draw();
        }
      }
      requestAnimationFrame(animate);
    };

    const shiftPoint = (p: any) => {
      const duration = 1 + 1 * Math.random();
      const delay = Math.random();

      // Simple organic movement
      const move = () => {
        const newX = p.originX - 50 + Math.random() * 100;
        const newY = p.originY - 50 + Math.random() * 100;

        // Manual easing for movement
        p.x = newX;
        p.y = newY;

        setTimeout(() => {
            if(animateHeader) move();
        }, duration * 2000);
      };

      move();
    };

    // Canvas drawing helpers
    const drawLines = (p: any) => {
      if (!p.active) return;
      for (const i in p.closest) {
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.closest[i].x, p.closest[i].y);
        // Adaptation: Using MitZay Primary Green
        ctx.strokeStyle = `rgba(0, 220, 1, ${p.active})`;
        ctx.stroke();
      }
    };

    function Circle(pos: any, rad: number, color: string) {
      this.pos = pos;
      this.radius = rad;
      this.color = color;
      this.active = 0;
      this.draw = function() {
        if (!this.active) return;
        ctx.beginPath();
        ctx.arc(this.pos.x, this.pos.y, this.radius, 0, 2 * Math.PI, false);
        ctx.fillStyle = `rgba(0, 220, 1, ${this.active})`;
        ctx.fill();
      };
    }

    const getDistance = (p1: any, p2: any) => {
      return Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2);
    };

    // Initialize
    initHeader();
    for (const i in points) {
      shiftPoint(points[i]);
    }
    animate();
    addListeners();

    return () => {
      animateHeader = false;
      window.removeEventListener('resize', resize);
    };
  }, []);

  return (
    <div 
      ref={containerRef}
      className="horizontal-section relative overflow-hidden bg-black flex items-center justify-center"
      style={{
        backgroundImage: "url('https://www.marcoguglie.it/Codepen/AnimatedHeaderBg/demo-1/img/demo-1-bg.jpg')",
