      <div className="relative z-10 text-center px-6 max-w-5xl">
        <h2 className="text-primary text-xs font-black tracking-[0.6em] uppercase mb-6 animate-pulse">
          Neural Nexus
        </h2>

        <h3 className="text-white font-montserrat font-black leading-tight mb-8">
          <span className="block text-4xl sm:text-6xl md:text-8xl uppercase tracking-[0.15em] mb-2">
            EL FUTURO ES
