import React, { useEffect, useRef } from 'react';

const NeuralNexusSection: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width: number, height: number, points: any[], target: {x: number, y: number}, animateHeader = true;

    const initHeader = () => {
      width = containerRef.current?.clientWidth || window.innerWidth;
      height = containerRef.current?.clientHeight || window.innerHeight;
      target = { x: width / 2, y: height / 2 };

      canvas.width = width;
      canvas.height = height;

      points = [];
      const spacing = width > 768 ? 35 : 18; 
      for (let x = 0; x < width; x = x + width / spacing) {
        for (let y = 0; y < height; y = y + height / spacing) {
          const px = x + Math.random() * width / spacing;
          const py = y + Math.random() * height / spacing;
          const p = { x: px, originX: px, y: py, originY: py };
          points.push(p);
        }
      }

      for (let i = 0; i < points.length; i++) {
        const closest = [];
        const p1 = points[i];
        for (let j = 0; j < points.length; j++) {
          const p2 = points[j];
          if (p1 !== p2) {
            let placed = false;
            for (let k = 0; k < 5; k++) {
              if (!placed) {
                if (closest[k] === undefined) {
                  closest[k] = p2;
                  placed = true;
                }
              }
            }
            for (let k = 0; k < 5; k++) {
              if (!placed) {
                if (getDistance(p1, p2) < getDistance(p1, closest[k])) {
                  closest[k] = p2;
                  placed = true;
                }
              }
            }
          }
        }
        p1.closest = closest;
      }

      for (const i in points) {
        const c = new Circle(points[i], 2 + Math.random() * 2, 'rgba(255,255,255,0.3)');
        points[i].circle = c;
      }
    };

    const addListeners = () => {
      if (!('ontouchstart' in window)) {
        window.addEventListener('mousemove', mouseMove);
      }
      window.addEventListener('resize', resize);
    };

    const mouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      target.x = e.clientX - rect.left;
      target.y = e.clientY - rect.top;
    };

    const resize = () => {
      if (!containerRef.current) return;
      width = containerRef.current.clientWidth;
      height = containerRef.current.clientHeight;
      canvas.width = width;
      canvas.height = height;
    };

    const animate = () => {
      if (animateHeader) {
        ctx.clearRect(0, 0, width, height);
        for (const i in points) {
          const dist = getDistance(target, points[i]);
          if (dist < 5000) {
            points[i].active = 0.4;
            points[i].circle.active = 0.8;
          } else if (dist < 25000) {
            points[i].active = 0.2;
            points[i].circle.active = 0.4;
          } else if (dist < 55000) {
            points[i].active = 0.05;
            points[i].circle.active = 0.15;
          } else {
            points[i].active = 0;
            points[i].circle.active = 0;
          }

          drawLines(points[i]);
          points[i].circle.draw();
        }
      }
      requestAnimationFrame(animate);
    };

    const shiftPoint = (p: any) => {
      const duration = 1 + 2 * Math.random();
      const move = () => {
        const newX = p.originX - 40 + Math.random() * 80;
        const newY = p.originY - 40 + Math.random() * 80;
        p.x = newX;
        p.y = newY;
        setTimeout(() => {
            if(animateHeader) move();
        }, duration * 2500);
      };
      move();
    };

    const drawLines = (p: any) => {
      if (!p.active) return;
      for (const i in p.closest) {
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.closest[i].x, p.closest[i].y);
        ctx.strokeStyle = `rgba(0, 220, 1, ${p.active})`;
        ctx.lineWidth = 0.8;
        ctx.stroke();
      }
    };

    function Circle(pos: any, rad: number, color: string) {
      this.pos = pos;
      this.radius = rad;
      this.active = 0;
      this.draw = function() {
        if (!this.active) return;
        ctx.beginPath();
        ctx.arc(this.pos.x, this.pos.y, this.radius, 0, 2 * Math.PI, false);
        ctx.fillStyle = `rgba(0, 220, 1, ${this.active})`;
        ctx.fill();
        // Glow effect
        ctx.shadowBlur = 15;
        ctx.shadowColor = 'rgba(0, 220, 1, 0.5)';
      };
    }

    const getDistance = (p1: any, p2: any) => {
      return Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2);
    };

    initHeader();
    for (const i in points) {
      shiftPoint(points[i]);
    }
    animate();
    addListeners();

    return () => {
      animateHeader = false;
      window.removeEventListener('mousemove', mouseMove);
      window.removeEventListener('resize', resize);
    };
  }, []);

  return (
    <div 
      ref={containerRef}
      className="horizontal-section relative overflow-hidden bg-black flex items-center justify-center cursor-crosshair"
      style={{
        backgroundImage: "url('https://www.marcoguglie.it/Codepen/AnimatedHeaderBg/demo-1/img/demo-1-bg.jpg')",
        backgroundSize: 'cover',
        backgroundPosition: 'center center'
      }}
    >
      <canvas ref={canvasRef} className="absolute inset-0 z-0" />

      <div className="relative z-10 text-center px-8">
        <div className="main-title">
          <h3 className="text-white font-montserrat font-black leading-[0.9] select-none pointer-events-none">
            <span className="block text-5xl sm:text-7xl md:text-[7rem] lg:text-[9rem] uppercase tracking-[-0.02em] mb-4">
              FUTURO
            </span>
            <span className="block text-4xl sm:text-6xl md:text-[6rem] lg:text-[7.5rem] font-thin tracking-[0.25em] text-primary/90 filter drop-shadow-[0_0_40px_rgba(0,220,1,0.5)]">
              AUTÓNOMO
            </span>
          </h3>
        </div>

        <p className="mt-12 text-gray-300 text-sm md:text-xl max-w-2xl mx-auto leading-relaxed font-light tracking-[0.15em] uppercase opacity-80 border-t border-primary/20 pt-8">
          Evolucionamos tu negocio con <span className="text-primary font-bold">inteligencia real</span>.
        </p>
      </div>
    </div>
  );
};

