import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import anime from 'https://esm.sh/animejs@3.2.2';
import { createNoise3D, createNoise4D } from 'https://esm.sh/simplex-noise@4.0.1';

const NeuralNexusSection: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [shapeName, setShapeName] = useState('Sphere');

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;

    let scene: THREE.Scene, 
        camera: THREE.PerspectiveCamera, 
        renderer: THREE.WebGLRenderer, 
        controls: OrbitControls, 
        clock: THREE.Clock;
    let composer: EffectComposer;
    let particleSystem: THREE.Points;
    let particlesGeometry: THREE.BufferGeometry;

    const CONFIG = {
      particleCount: 12000,
      shapeSize: 12,
      noiseMaxStrength: 2.5,
      morphDuration: 3000,
      bloomStrength: 1.5,
    };

    const noise3D = createNoise3D();
    const noise4D = createNoise4D();
    clock = new THREE.Clock();

    // Shape Generators
    const generateSphere = (count: number, size: number) => {
      const points = new Float32Array(count * 3);
      const phi = Math.PI * (Math.sqrt(5) - 1);
      for (let i = 0; i < count; i++) {
        const y = 1 - (i / (count - 1)) * 2;
        const radius = Math.sqrt(1 - y * y);
        const theta = phi * i;
        points[i * 3] = Math.cos(theta) * radius * size;
        points[i * 3 + 1] = y * size;
        points[i * 3 + 2] = Math.sin(theta) * radius * size;
      }
      return points;
    };

    const generateTorus = (count: number, size: number) => {
      const points = new Float32Array(count * 3);
      const R = size * 0.8; const r = size * 0.4;
      for (let i = 0; i < count; i++) {
        const theta = Math.random() * Math.PI * 2; const phi = Math.random() * Math.PI * 2;
        points[i * 3] = (R + r * Math.cos(phi)) * Math.cos(theta);
        points[i * 3 + 1] = r * Math.sin(phi);
        points[i * 3 + 2] = (R + r * Math.cos(phi)) * Math.sin(theta);
      }
      return points;
    };

    const generateGalaxy = (count: number, size: number) => {
      const points = new Float32Array(count * 3);
      for (let i = 0; i < count; i++) {
        const t = Math.pow(Math.random(), 1.5); const radius = t * size;
        const angle = (radius / size * 8) + (Math.floor(Math.random() * 4) * Math.PI / 2);
        points[i * 3] = radius * Math.cos(angle + (Math.random() - 0.5) * 0.5);
        points[i * 3 + 1] = (Math.random() - 0.5) * size * 0.1 * (1 - radius / size);
        points[i * 3 + 2] = radius * Math.sin(angle + (Math.random() - 0.5) * 0.5);
      }
      return points;
    };

    const generateWave = (count: number, size: number) => {
      const points = new Float32Array(count * 3);
      for (let i = 0; i < count; i++) {
        const u = Math.random() * 2 - 1; const v = Math.random() * 2 - 1;
        const x = u * size; const z = v * size;
        const dist = Math.sqrt(u * u + v * v);
        points[i * 3] = x;
        points[i * 3 + 1] = Math.sin(dist * Math.PI * 2) * size * 0.3 * (1 - dist);
        points[i * 3 + 2] = z;
      }
      return points;
    };

    const SHAPES = [
      { name: 'Sphere', gen: generateSphere },
      { name: 'Torus', gen: generateTorus },
      { name: 'Galaxy', gen: generateGalaxy },
      { name: 'Wave', gen: generateWave }
    ];
    let currentShapeIdx = 0;

    let targetPositions = SHAPES.map(s => s.gen(CONFIG.particleCount, CONFIG.shapeSize));
    let currentPositions = new Float32Array(targetPositions[0]);
    let sourcePositions = new Float32Array(targetPositions[0]);
    let morphProgress = { val: 0 };
    let isMorphing = false;

    // Initialization
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(75, containerRef.current.clientWidth / containerRef.current.clientHeight, 0.1, 1000);
    camera.position.z = 25;

    renderer = new THREE.WebGLRenderer({ canvas: canvasRef.current, antialias: true, alpha: true });
    renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;
    controls.enableZoom = false;

    // Post processing
    composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), CONFIG.bloomStrength, 0.4, 0.1);
    composer.addPass(bloomPass);

    // Particle System
    particlesGeometry = new THREE.BufferGeometry();
    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(currentPositions, 3));

    const colors = new Float32Array(CONFIG.particleCount * 3);
    const sizes = new Float32Array(CONFIG.particleCount);
    for (let i = 0; i < CONFIG.particleCount; i++) {
      // MitZay Themed Colors (Green to Cyan)
      const color = new THREE.Color(i % 2 === 0 ? '#00DC01' : '#00ffd5');
      color.toArray(colors, i * 3);
      sizes[i] = Math.random() * 0.15 + 0.05;
    }
    particlesGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    particlesGeometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

    const material = new THREE.ShaderMaterial({
      vertexShader: `
        attribute float size;
        varying vec3 vColor;
        void main() {
          vColor = color;
          vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (300.0 / -mvPosition.z);
          gl_Position = projectionMatrix * mvPosition;
        }
      `,
      fragmentShader: `
        varying vec3 vColor;
        void main() {
          if (length(gl_PointCoord - vec2(0.5)) > 0.5) discard;
          gl_FragColor = vec4(vColor, 1.0);
        }
      `,
      transparent: true,
      vertexColors: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });

    particleSystem = new THREE.Points(particlesGeometry, material);
    scene.add(particleSystem);

    const triggerMorph = () => {
      if (isMorphing) return;
      isMorphing = true;
      sourcePositions.set(currentPositions);
      currentShapeIdx = (currentShapeIdx + 1) % SHAPES.length;
      setShapeName(SHAPES[currentShapeIdx].name);

      morphProgress.val = 0;
      anime({
        targets: morphProgress,
        val: 1,
        duration: CONFIG.morphDuration,
        easing: 'easeInOutQuart',
        complete: () => {
          isMorphing = false;
        }
      });
    };

    const animate = () => {
      const elapsed = clock.getElapsedTime();
      const delta = clock.getDelta();
      controls.update();

      const posAttr = particlesGeometry.attributes.position.array as Float32Array;
      const targets = targetPositions[currentShapeIdx];

      for (let i = 0; i < CONFIG.particleCount; i++) {
        const i3 = i * 3;
        const px = isMorphing ? THREE.MathUtils.lerp(sourcePositions[i3], targets[i3], morphProgress.val) : targets[i3];
        const py = isMorphing ? THREE.MathUtils.lerp(sourcePositions[i3+1], targets[i3+1], morphProgress.val) : targets[i3+1];
        const pz = isMorphing ? THREE.MathUtils.lerp(sourcePositions[i3+2], targets[i3+2], morphProgress.val) : targets[i3+2];

        // Noise flow
        const n = noise4D(px * 0.1, py * 0.1, pz * 0.1, elapsed * 0.2);
        posAttr[i3] = px + n * 0.5;
        posAttr[i3+1] = py + n * 0.5;
        posAttr[i3+2] = pz + n * 0.5;

        // Update currentPositions for next morph source
        currentPositions[i3] = posAttr[i3];
        currentPositions[i3+1] = posAttr[i3+1];
        currentPositions[i3+2] = posAttr[i3+2];
      }
      particlesGeometry.attributes.position.needsUpdate = true;

      composer.render();
      requestAnimationFrame(animate);
    };

    animate();

    const handleResize = () => {
      if (!containerRef.current) return;
      camera.aspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
      composer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('click', triggerMorph);

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('click', triggerMorph);
      renderer.dispose();
    };
  }, []);

  return (
    <div 
      ref={containerRef}
      className="horizontal-section relative overflow-hidden bg-black flex items-center justify-center cursor-pointer group"
    >
      {/* Background Atmosphere */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(0,220,1,0.05)_0%,transparent_70%)] pointer-events-none"></div>

      <canvas ref={canvasRef} className="absolute inset-0 z-0" />

      <div className="relative z-10 text-center px-8 pointer-events-none">
        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-primary/20 bg-primary/5 backdrop-blur-sm mb-6 animate-pulse">
           <span className="w-1.5 h-1.5 rounded-full bg-primary"></span>
           <span className="text-[8px] font-black uppercase tracking-[0.4em] text-primary">Sistema: {shapeName}</span>
        </div>

        <h3 className="text-white font-montserrat font-black leading-[0.9] select-none">
          <span className="block text-4xl sm:text-6xl md:text-[6rem] lg:text-[8rem] uppercase tracking-[-0.02em] mb-2 opacity-90">
            FUTURO
          </span>
          <span className="block text-3xl sm:text-5xl md:text-[5rem] lg:text-[6.5rem] font-thin tracking-[0.3em] text-primary/80 drop-shadow-[0_0_50px_rgba(0,220,1,0.3)]">
            AUTÓNOMO
          </span>
        </h3>

        <p className="mt-8 text-gray-400 text-xs md:text-sm max-w-xl mx-auto leading-relaxed font-light tracking-[0.2em] uppercase opacity-60">
          Haz clic para evolucionar el núcleo • MitZay Agency IA
        </p>
      </div>

      {/* Decorative corners */}
      <div className="absolute top-10 left-10 w-20 h-20 border-t border-l border-primary/20 pointer-events-none"></div>
      <div className="absolute bottom-10 right-10 w-20 h-20 border-b border-r border-primary/20 pointer-events-none"></div>
    </div>
  );
};

export default NeuralNexusSection;

