        const u = Math.random() * 2 - 1; const v = Math.random() * 2 - 1;
        const x = u * size; const z = v * size;
        const dist = Math.sqrt(u * u + v * v);
        points[i * 3] = x;
        points[i * 3 + 1] = Math.sin(dist * Math.PI * 2) * size * 0.3 * (1 - dist);
        points[i * 3 + 2] = z;
      }
      return points;
    };

