        easing: 'easeInOutExpo',
        complete: () => {
          isMorphing = false;
        }
      });
    };

    const animate = () => {
      const elapsed = clock.getElapsedTime();
      controls.update();

      const posAttr = particlesGeometry.attributes.position.array as Float32Array;
      const targets = targetPositions[currentShapeIdx];

      for (let i = 0; i < CONFIG.particleCount; i++) {
