        const t = Math.pow(Math.random(), 1.5); const radius = t * size;
        const angle = (radius / size * 8) + (Math.floor(Math.random() * 4) * Math.PI / 2);
        points[i * 3] = radius * Math.cos(angle + (Math.random() - 0.5) * 0.5);
        points[i * 3 + 1] = (Math.random() - 0.5) * size * 0.1 * (1 - radius / size);
        points[i * 3 + 2] = radius * Math.sin(angle + (Math.random() - 0.5) * 0.5);
      }
      return points;
    };

    const generateWave = (count: number, size: number) => {
      const points = new Float32Array(count * 3);
      for (let i = 0; i < count; i++) {
        const u = Math.random() * 2 - 1; const v = Math.random() * 2 - 1;
        const x = u * size; const z = v * size;
        const dist = Math.sqrt(u * u + v * v);
        points[i * 3] = x;
        points[i * 3 + 1] = Math.sin(dist * Math.PI * 2) * size * 0.3 * (1 - dist);
        points[i * 3 + 2] = z;
      }
      return points;
    };

    const SHAPES = [
      { name: 'Nucleus', gen: generateSphere },
      { name: 'Helix', gen: generateTorus },
      { name: 'Void', gen: generateGalaxy },
      { name: 'Flow', gen: generateWave }
    ];
    let currentShapeIdx = 0;

    let targetPositions = SHAPES.map(s => s.gen(CONFIG.particleCount, CONFIG.shapeSize));
    let currentPositions = new Float32Array(targetPositions[0]);
    let sourcePositions = new Float32Array(targetPositions[0]);
    let morphProgress = { val: 0 };
    let isMorphing = false;

    // Initialize Scene
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(75, containerRef.current.clientWidth / containerRef.current.clientHeight, 0.1, 2000);
    camera.position.z = 30;

    renderer = new THREE.WebGLRenderer({ canvas: canvasRef.current, antialias: true, alpha: true });
    renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;
    controls.enableZoom = false;

    // Background Starfield
    const createStarfield = () => {
      const starGeo = new THREE.BufferGeometry();
      const starPos = new Float32Array(CONFIG.starCount * 3);
      const starSizes = new Float32Array(CONFIG.starCount);
      const starColors = new Float32Array(CONFIG.starCount * 3);

      for(let i = 0; i < CONFIG.starCount; i++) {
        const r = 200 + Math.random() * 600;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);
        starPos[i*3] = r * Math.sin(phi) * Math.cos(theta);
        starPos[i*3+1] = r * Math.sin(phi) * Math.sin(theta);
        starPos[i*3+2] = r * Math.cos(phi);
        starSizes[i] = Math.random() * 0.5 + 0.1;
        const starColor = new THREE.Color().setHSL(0.6, 0.2, 0.8 + Math.random() * 0.2);
        starColor.toArray(starColors, i*3);
      }
      starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
      starGeo.setAttribute('size', new THREE.BufferAttribute(starSizes, 1));
      starGeo.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

      const starMat = new THREE.ShaderMaterial({
        uniforms: { pointTexture: { value: createStarTexture() } },
        vertexShader: `
          attribute float size;
          varying vec3 vColor;
          void main() {
            vColor = color;
            vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
            gl_PointSize = size * (600.0 / -mvPosition.z);
            gl_Position = projectionMatrix * mvPosition;
          }
        `,
        fragmentShader: `
          uniform sampler2D pointTexture;
          varying vec3 vColor;
          void main() {
            gl_FragColor = vec4(vColor, texture2D(pointTexture, gl_PointCoord).a * 0.7);
          }
        `,
        blending: THREE.AdditiveBlending,
        transparent: true,
        vertexColors: true,
        depthWrite: false
      });
      starfield = new THREE.Points(starGeo, starMat);
      scene.add(starfield);
    };
    createStarfield();

    // Post Processing
    composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), CONFIG.bloomStrength, 0.6, 0.1);
    composer.addPass(bloomPass);

    // Particle System
    particlesGeometry = new THREE.BufferGeometry();
    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(currentPositions, 3));

    const colorsArr = new Float32Array(CONFIG.particleCount * 3);
    const sizesArr = new Float32Array(CONFIG.particleCount);
    for (let i = 0; i < CONFIG.particleCount; i++) {
      sizesArr[i] = Math.random() * 0.2 + 0.08;
    }
    particlesGeometry.setAttribute('color', new THREE.BufferAttribute(colorsArr, 3));
    particlesGeometry.setAttribute('size', new THREE.BufferAttribute(sizesArr, 1));

    // Dynamic Color Update Function
    const updateColors = () => {
      const scheme = COLOR_SCHEMES[activeScheme as keyof typeof COLOR_SCHEMES] || COLOR_SCHEMES.neon;
      const positions = particlesGeometry.attributes.position.array as Float32Array;
      const colors = particlesGeometry.attributes.color.array as Float32Array;

      for (let i = 0; i < CONFIG.particleCount; i++) {
        const i3 = i * 3;
        const x = positions[i3];
        const y = positions[i3+1];
        const z = positions[i3+2];
        const dist = Math.sqrt(x*x + y*y + z*z);
        const maxRadius = CONFIG.shapeSize * 1.2;

        let hue;
        if (activeScheme === 'rainbow') {
          hue = ((x / maxRadius + 1) * 180 + (y / maxRadius + 1) * 180) % 360;
        } else {
          hue = THREE.MathUtils.mapLinear(dist, 0, maxRadius, scheme.startHue, scheme.endHue);
        }

        const color = new THREE.Color().setHSL(hue / 360, scheme.saturation, scheme.lightness);
        color.toArray(colors, i3);
      }
      particlesGeometry.attributes.color.needsUpdate = true;
    };
    updateColorsRef.current = updateColors;
    updateColors();

    const material = new THREE.ShaderMaterial({
      vertexShader: `
        attribute float size;
        varying vec3 vColor;
        void main() {
          vColor = color;
          vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (500.0 / -mvPosition.z);
          gl_Position = projectionMatrix * mvPosition;
        }
      `,
      fragmentShader: `
        varying vec3 vColor;
        void main() {
          float dist = length(gl_PointCoord - vec2(0.5));
          if (dist > 0.5) discard;
          float alpha = 1.0 - smoothstep(0.3, 0.5, dist);
          gl_FragColor = vec4(vColor, alpha);
        }
      `,
      transparent: true,
      vertexColors: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });

    particleSystem = new THREE.Points(particlesGeometry, material);
    scene.add(particleSystem);

    const triggerMorph = () => {
      if (isMorphing) return;
      isMorphing = true;
      sourcePositions.set(currentPositions);
      currentShapeIdx = (currentShapeIdx + 1) % SHAPES.length;
      setShapeName(SHAPES[currentShapeIdx].name);

      morphProgress.val = 0;
      anime({
        targets: morphProgress,
        val: 1,
        duration: CONFIG.morphDuration,
        easing: 'easeInOutExpo',
        complete: () => {
          isMorphing = false;
        }
      });
    };
    triggerMorphRef.current = triggerMorph;

    const animate = () => {
      const elapsed = clock.getElapsedTime();
      controls.update();

      const posAttr = particlesGeometry.attributes.position.array as Float32Array;
      const targets = targetPositions[currentShapeIdx];

      for (let i = 0; i < CONFIG.particleCount; i++) {
        const i3 = i * 3;
        const px = isMorphing ? THREE.MathUtils.lerp(sourcePositions[i3], targets[i3], morphProgress.val) : targets[i3];
        const py = isMorphing ? THREE.MathUtils.lerp(sourcePositions[i3+1], targets[i3+1], morphProgress.val) : targets[i3+1];
        const pz = isMorphing ? THREE.MathUtils.lerp(sourcePositions[i3+2], targets[i3+2], morphProgress.val) : targets[i3+2];

        const n = noise4D(px * 0.1, py * 0.1, pz * 0.1, elapsed * 0.15);
        posAttr[i3] = px + n * 0.5;
        posAttr[i3+1] = py + n * 0.5;
        posAttr[i3+2] = pz + n * 0.5;

        currentPositions[i3] = posAttr[i3];
        currentPositions[i3+1] = posAttr[i3+1];
        currentPositions[i3+2] = posAttr[i3+2];
      }
      particlesGeometry.attributes.position.needsUpdate = true;

      // Update starfield subtly
      starfield.rotation.y = elapsed * 0.01;
      starfield.rotation.x = elapsed * 0.005;

      composer.render();
      requestAnimationFrame(animate);
    };

    animate();

    const handleResize = () => {
      if (!containerRef.current) return;
      camera.aspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
      composer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, []);

  // Sync React state with Three.js ref logic
  useEffect(() => {
    updateColorsRef.current();
  }, [activeScheme]);

  return (
    <div 
      ref={containerRef}
      className="horizontal-section relative overflow-hidden bg-black flex items-center justify-center group"
    >
      <canvas ref={canvasRef} className="absolute inset-0 z-0" onClick={() => triggerMorphRef.current()} />

      {/* UI OVERLAY */}
      <div className="relative z-10 text-center px-8 pointer-events-none flex flex-col items-center">
        <div className="flex items-center gap-2 mb-4">
          <div className="w-1.5 h-1.5 bg-primary rounded-full animate-pulse shadow-[0_0_10px_#00DC01]"></div>
          <div className="text-[9px] font-black uppercase tracking-[0.5em] text-primary/80">
            NEXUS CORE • ONLINE
          </div>
        </div>

        <h3 className="text-white font-montserrat font-black leading-none select-none flex flex-col items-center mb-6">
          <span className="text-3xl md:text-5xl lg:text-6xl uppercase tracking-[-0.04em] mb-1">
            VISIÓN
          </span>
          <span className="text-2xl md:text-4xl lg:text-5xl font-thin tracking-[0.4em] text-primary drop-shadow-[0_0_20px_rgba(0,220,1,0.5)]">
            AUTÓNOMA
          </span>
        </h3>

        <div className="w-12 h-[1px] bg-primary/20 mb-6"></div>
        <p className="text-gray-400 text-[10px] md:text-xs font-light tracking-[0.4em] uppercase max-w-xs text-center leading-relaxed mb-8 opacity-60">
          Escalabilidad Digital • IA
        </p>

        {/* Color Picker Interface */}
        <div className="flex items-center gap-4 pointer-events-auto bg-black/40 backdrop-blur-md px-6 py-3 rounded-full border border-white/5">
          {Object.entries(COLOR_SCHEMES).map(([key, scheme]) => (
            <button
              key={key}
              onClick={() => setActiveScheme(key as any)}
              className={`w-4 h-4 rounded-full border-2 transition-all ${
                activeScheme === key 
                ? 'border-white scale-125 shadow-[0_0_10px_white]' 
                : 'border-transparent opacity-40 hover:opacity-100'
              }`}
              style={{ 
                background: key === 'rainbow' 
                  ? 'linear-gradient(to right, red, yellow, green, cyan, blue, magenta)' 
                  : `hsl(${scheme.startHue}, 100%, 50%)` 
              }}
              title={scheme.label}
            />
          ))}
          <div className="w-[1px] h-4 bg-white/10 mx-2"></div>
          <div className="text-[8px] font-black uppercase tracking-[0.2em] text-primary/80">
            MODO: {shapeName}
          </div>
        </div>

        <p className="mt-6 text-[8px] text-gray-600 uppercase tracking-widest animate-bounce">
          Clic en el núcleo para evolucionar
        </p>
      </div>

      {/* Aesthetic Frames */}
      <div className="absolute top-16 left-16 w-12 h-12 border-t border-l border-primary/30 pointer-events-none"></div>
      <div className="absolute bottom-16 right-16 w-12 h-12 border-b border-r border-primary/30 pointer-events-none"></div>
    </div>
  );
};

