          const v1 = baseVertices[faceIndex]; const v2 = baseVertices[(faceIndex + 1) % 4];
          let u = Math.random(); let v = Math.random();
          if (u + v > 1) { u = 1 - u; v = 1 - v; }
          p.addVectors(v1, new THREE.Vector3().subVectors(v2, v1).multiplyScalar(u));
