          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) throw new Error('Error en el servidor');

      // Si llegamos aquí, n8n respondió exitosamente
      setStep(2);
    } catch (err) {
      console.error("Error enviando datos a n8n:", err);
