              </div>
              <div>
                <h3 className="text-4xl font-black mb-3">¡BIENVENIDO AL ELITE!</h3>
                <p className="text-gray-400 text-sm">Tu código ha sido activado y enviado a <span className="text-white">{formData.email}</span>.</p>
