  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    fullName: '',
    whatsapp: '',
    email: ''
  });

  if (!isOpen) return null;

  const handleCopy = () => {
    navigator.clipboard.writeText(DISCOUNT_CONFIG.code);
    setCopied(true);
