      <Navbar currentPage={currentPage} onNavigate={setCurrentPage} onScrollToSection={scrollToSection} />

      <main className="md:pl-20 h-full">
        {currentPage === 'home' && (
          <div className="relative h-screen w-full overflow-hidden bg-black">
